import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import '../../../services/personal_ai/campaign_ai_service.dart';
import '../../messenger/presentation/messenger_screen.dart';
class AurenCampaignAiScreen extends StatefulWidget{const AurenCampaignAiScreen({super.key});@override State<AurenCampaignAiScreen> createState()=>_AurenCampaignAiScreenState();}
class _AurenCampaignAiScreenState extends State<AurenCampaignAiScreen>{final objective=TextEditingController(text:'زيادة الوصول والعملاء');final audience=TextEditingController(text:'عملاء محتملون');String channel='Pulse';AurenCampaignPlan? plan;bool loading=false;
Future<void> _build()async{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)return;setState(()=>loading=true);try{final p=await CampaignAiService().build(uid,objective:objective.text,audience:audience.text,channel:channel);if(mounted)setState(()=>plan=p);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر بناء الحملة: '+e.toString())));}finally{if(mounted)setState(()=>loading=false);}}
