@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Campaign AI')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Campaign AI',style:TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:6),const Text('حوّل هدفك التجاري إلى حملة قابلة للاختبار والقياس بدون إرسال أو نشر تلقائي.'),const SizedBox(height:16),TextField(controller:objective,decoration:const InputDecoration(labelText:'هدف الحملة')),const SizedBox(height:10),TextField(controller:audience,decoration:const InputDecoration(labelText:'الجمهور المستهدف')),const SizedBox(height:10),DropdownButtonFormField<String>(value:channel,items:const ['Pulse','Messenger','Creator','Marketplace'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>channel=v??'Pulse'),decoration:const InputDecoration(labelText:'القناة')),const SizedBox(height:12),FilledButton.icon(onPressed:loading?null:_build,icon:const Icon(Icons.campaign_outlined),label:Text(loading?'جاري البناء…':'ابنِ الحملة')),if(plan!=null)...[const SizedBox(height:18),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(plan!.businessName,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text(plan!.objective),const Divider(),const Text('أفكار المحتوى',style:TextStyle(fontWeight:FontWeight.bold)),...plan!.contentIdeas.map((x)=>ListTile(leading:const Icon(Icons.lightbulb_outline),title:Text(x),contentPadding:EdgeInsets.zero)),const Divider(),const Text('خطوات التنفيذ',style:TextStyle(fontWeight:FontWeight.bold)),...List.generate(plan!.steps.length,(i)=>ListTile(leading:CircleAvatar(child:Text((i+1).toString())),title:Text(plan!.steps[i]),contentPadding:EdgeInsets.zero)),const Divider(),const Text('المقاييس',style:TextStyle(fontWeight:FontWeight.bold)),Text(plan!.metrics.join(' • ')),const SizedBox(height:12),FilledButton.tonalIcon(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>MessengerScreen(initialPrompt:'حلّل حملة '+plan!.businessName+' بهدف '+plan!.objective+' للجمهور '+plan!.audience+' على '+plan!.channel+'. اقترح تحسينات ولا تنشر أو ترسل أي شيء بدون موافقتي.'))),icon:const Icon(Icons.chat),label:const Text('حلّل الحملة مع AUREN'))]))]]));}